"""Five tests, one per student function. Do not edit this file."""

import pytest
from payroll import (
    parse_employee, validate_employee, calculate_pay,
    process_employee, process_payroll,
)


def test_parse_employee():
    raw = {"name": "Floppsie", "hours": "40", "rate": "25"}
    parsed = parse_employee(raw)
    assert parsed == {"name": "Floppsie", "hours": 40.0, "rate": 25.0}
    assert raw["hours"] == "40"  # Do not modify the original record.
    for bad in ("banana", None):
        with pytest.raises(ValueError, match=r"^Invalid numeric payroll data\.$"):
            parse_employee({"name": "Peter", "hours": bad, "rate": "20"})
    with pytest.raises(KeyError):
        parse_employee({"name": "Carol", "hours": "40"})


def test_validate_employee():
    assert validate_employee({"name": "Alice", "hours": 0.0, "rate": 0.01}) is True
    assert validate_employee({"name": "Bob", "hours": 80.0, "rate": 500.0}) is True
    cases = [
        ({"name": "", "hours": 40.0, "rate": 20.0}, "Invalid employee name."),
        ({"name": None, "hours": 40.0, "rate": 20.0}, "Invalid employee name."),
        ({"name": "Peter", "hours": -1.0, "rate": 20.0}, "Invalid working hours."),
        ({"name": "Peter", "hours": 81.0, "rate": 20.0}, "Invalid working hours."),
        ({"name": "Peter", "hours": 40.0, "rate": 0.0}, "Invalid hourly rate."),
        ({"name": "Peter", "hours": 40.0, "rate": 501.0}, "Invalid hourly rate."),
    ]
    for employee, message in cases:
        with pytest.raises(ValueError) as exc:
            validate_employee(employee)
        assert str(exc.value) == message


def test_calculate_pay():
    for hours, rate, expected in [(0, 25, 0), (40, 25, 1000),
                                  (45, 20, 950), (42, 22.5, 967.5)]:
        assert calculate_pay({"name": "Test", "hours": hours, "rate": rate}) == pytest.approx(expected)


def test_process_employee():
    summary = {"attempted": 0, "successful": 0, "rejected": 0}
    paid = process_employee({"name": "Alice", "hours": "45", "rate": "20"}, summary)
    assert paid == {"name": "Alice", "status": "PAID", "pay": 950.0}
    rejected = process_employee({"name": "Peter", "hours": "-5", "rate": "18"}, summary)
    assert rejected == {"name": "Peter", "status": "REJECTED", "error": "Invalid working hours."}
    missing = process_employee({"hours": "40", "rate": "20"}, summary)
    assert missing["name"] == "Unknown" and missing["status"] == "REJECTED"
    assert missing["error"]  # Missing-key error is reported.
    assert summary == {"attempted": 3, "successful": 1, "rejected": 2}


def test_process_payroll():
    records = [
        {"name": "Floppsie", "hours": "40", "rate": "25"},
        {"name": "Peter", "hours": "-5", "rate": "18"},
        {"name": "Felicity", "hours": "45", "rate": "20"},
        {"name": "Goldhoarder", "hours": "50", "rate": "banana"},
        {"name": "Alice", "hours": "35", "rate": "30"},
    ]
    report = process_payroll(records)
    assert report["summary"] == {"attempted": 5, "successful": 3, "rejected": 2}
    assert [r["status"] for r in report["results"]] == ["PAID", "REJECTED", "PAID", "REJECTED", "PAID"]
    assert report["total_pay"] == pytest.approx(3000.0)
    empty = process_payroll([])
    assert empty == {"results": [], "summary": {"attempted": 0, "successful": 0, "rejected": 0}, "total_pay": 0.0}
